import java.util.Collections
import java.util.HashMap

/**
 * map 범용 사전. CharSequence : CharSequence[] pair이다. 만약 value에 Object[]를 사용하길
 * 원한다면 custom dictionary를 사용한다.
 */
open class MapDictionary : SourceDictionary<Any> {

    @JvmField
    protected var map: MutableMap<CharSequence, Array<CharSequence>>

    constructor() : this(false)

    constructor(ignoreCase: Boolean) : super(ignoreCase, null, 0, null, DictionaryType.MAP) {
        map = HashMap()
    }

    constructor(
        map: MutableMap<CharSequence, Array<CharSequence>>,
        ignoreCase: Boolean,
        label: String?,
        seq: Int,
        tokenType: String?,
        type: DictionaryType
    ) : super(ignoreCase, label, seq, tokenType, type) {
        this.map = map
    }

    constructor(
        file: File,
        ignoreCase: Boolean,
        label: String?,
        seq: Int,
        tokenType: String?,
        type: DictionaryType
    ) : super(ignoreCase, label, seq, tokenType, type) {
        if (!file.exists()) {
            map = HashMap()
            logger.error("사전파일이 존재하지 않습니다. file={}", file.absolutePath)
            return
        }
        var inputStream: InputStream? = null
        try {
            inputStream = FileInputStream(file)
            map = HashMap()
            readFrom(inputStream)
        } catch (e: IOException) {
            map = HashMap()
            logger.error("", e)
        } finally {
            try { inputStream?.close() } catch (ignore: Exception) { }
        }
    }

    constructor(
        inputStream: InputStream,
        ignoreCase: Boolean,
        label: String?,
        seq: Int,
        tokenType: String?,
        type: DictionaryType
    ) : super(ignoreCase, label, seq, tokenType, type) {
        map = HashMap()
        try {
            readFrom(inputStream)
        } catch (e: IOException) {
            logger.error("", e)
        }
    }

    override fun addEntry(keyword: CharSequence?, values: Array<Any?>?, columnList: List<Any>?) {
        if (keyword == null) return
        if (values == null) return
        val cv = CharVector(keyword.toString().trim(), ignoreCase)
        if (cv.length == 0) return
        val list = Array<CharSequence>(values.size) { inx ->
            CharVector(values[inx].toString(), ignoreCase)
        }
        map[cv.removeWhitespaces()] = list
    }

    fun getUnmodifiableMap(): Map<CharSequence, Array<CharSequence>> = Collections.unmodifiableMap(map)

    fun map(): MutableMap<CharSequence, Array<CharSequence>> = map

    fun setMap(map: MutableMap<CharSequence, Array<CharSequence>>) {
        this.map = map
    }

    fun containsKey(key: CharSequence): Boolean = map.containsKey(key)

    operator fun get(key: CharSequence): Array<CharSequence>? = map[key]

    @Throws(IOException::class)
    override fun writeTo(out: OutputStream) {
        val bufferedOut = if (out is BufferedOutputStream) out else BufferedOutputStream(out)
        val output: DataOutput = OutputStreamDataOutput(bufferedOut)
        val keySet = map.keys.iterator()
        // write size of map
        output.writeVInt(map.size)
        // write key and value map
        while (keySet.hasNext()) {
            // write key
            val keyCs = keySet.next()
            val key = CharVector.valueOf(keyCs)!!
            output.writeUString(key.array(), key.offset(), key.length)
            // write values
            val values = map[keyCs]!!
            output.writeVInt(values.size)
            for (v in values) {
                val value = CharVector.valueOf(v)!!
                output.writeUString(value.array(), value.offset(), value.length)
            }
        }
        try { bufferedOut.flush() } catch (ignore: Exception) { }
    }

    @Throws(IOException::class)
    override fun readFrom(input: InputStream) {
        val bufferedIn = if (input is BufferedInputStream) input else BufferedInputStream(input)
        val dataInput: DataInput = InputStreamDataInput(bufferedIn)
        map = HashMap()
        val size = dataInput.readVInt()
        for (entryInx in 0 until size) {
            val key: CharSequence = CharVector(dataInput.readUString(), ignoreCase)
            val valueLength = dataInput.readVInt()
            val values = Array<CharSequence>(valueLength) { valueInx ->
                CharVector(dataInput.readUString(), ignoreCase)
            }
            map[key] = values
        }
    }

    override fun addSourceLineEntry(line: CharSequence) {
        val kv = line.toString().split("\t")
        when (kv.size) {
            1 -> {
                val value = kv[0].trim()
                addEntry(null, arrayOf(value), null)
            }
            2 -> {
                val keyword = kv[0].trim()
                val value = kv[1].trim()
                addEntry(keyword, arrayOf(value), null)
            }
        }
    }

    override fun reload(obj: Any?) {
        if (obj != null && obj is MapDictionary) {
            this.map = obj.map()
        } else {
            throw IllegalArgumentException("Reload dictionary argument error. argument = $obj")
        }
    }

    companion object {
        private val logger = SourceDictionary.logger
    }
}

