    fun getWordSet(): MutableSet<CharSequence> = wordSet

    fun setWordSet(wordSet: MutableSet<CharSequence>) {
        this.wordSet = wordSet
    }

    fun getUnmodifiableWordSet(): Set<CharSequence> = Collections.unmodifiableSet(wordSet)

    private fun duplicateCharList(arr: Array<CharSequence>?): Array<CharSequence>? {
        return arr?.copyOf()
    }

    // key가 null일수 있다. 양방향의 경우.
    override fun addEntry(keyword: CharSequence?, values: Array<Any?>?, columnSettingList: List<Any>?) {
        val list = ArrayList<CharSequence>(4)
        var mainWord: CharVector? = null
        if (keyword != null) {
            mainWord = CharVector(keyword.toString().trim(), ignoreCase)
            if (mainWord.length > 0) {
                wordSet.add(mainWord)
                if (mainWord.hasWhitespaces()) {
                    for (w in CharVector.splitByWhitespace(mainWord)) {
                        wordSet.add(w)
                    }
                }
            }
        }

        if (values == null || values.isEmpty()) return
        // 0번째에 유사어들이 컴마 단위로 모두 입력되어 있으므로 [0]만 확인하면 된다.
        val valueString = values[0].toString()
        // 중복제거.
        val synonyms = valueString.split(",").toTypedArray()
        dedupSynonym(synonyms)
        for (k in synonyms.indices) {
            val synonym = synonyms[k].trim()
            if (synonym.isNotEmpty()) {
                val word = CharVector(synonym, ignoreCase)
                list.add(word)
                wordSet.add(word)
                if (word.hasWhitespaces()) {
                    for (w in CharVector.splitByWhitespace(word)) {
                        wordSet.add(w)
                    }
                }
            }
        }

        if (mainWord == null) {
            // 양방향.
            for (j in list.indices) {
                var key: CharSequence = CharVector.valueOf(list[j])!!
                var value = arrayOfNulls<CharSequence>(list.size - 1)
                var idx = 0
                for (k in list.indices) {
                    val v = list[k]
                    if (key != v) {
                        // 다른것만 value로 넣는다.
                        value[idx++] = v
                    }
                }
                // 유사어사전 데이터에 대표단어와 동일한 단어가 여러개 있을경우, 최종리스트는 더 적어지게 되므로 전체 array
                // 길이를 줄여준다.
                if (idx < value.size) {
                    value = Arrays.copyOf(value, idx)
                }

                @Suppress("UNCHECKED_CAST")
                var finalValue = value as Array<CharSequence>
                if (finalValue.isNotEmpty()) {
                    val value2 = map[key]
                    if (value2 != null) {
                        // 이전값과 머징.
                        val dupValue2 = duplicateCharList(value2)
                        finalValue = mergeSynonyms(dupValue2!!, finalValue)
                    }
                    map[key] = finalValue
                    // 공백을 제거한 key도 하나더 만든다.
                    if ((key as CharVector).hasWhitespaces()) {
                        key = CharVector(key.toString(), ignoreCase).removeWhitespaces()
                        val value2Inner: Array<CharSequence>? = map[key]
                        var mergedValue = finalValue
                        if (value2Inner != null) {
                            // 이전값과 머징.
                            val dupValue2Inner = duplicateCharList(value2Inner)
                            mergedValue = mergeSynonyms(dupValue2Inner!!, finalValue)
                        }
                        map[key] = mergedValue
                    }
                }
            }
        } else {
            // 단방향.
            var value = arrayOfNulls<CharSequence>(list.size)
            var idx = 0
            for (j in value.indices) {
                val word = list[j]
                if (mainWord != word) {
                    // 다른것만 value로 넣는다.
                    value[idx++] = word
                }
            }
            if (idx < value.size) {
                value = Arrays.copyOf(value, idx)
            }
            @Suppress("UNCHECKED_CAST")
            var finalValue = value as Array<CharSequence>
            if (finalValue.isNotEmpty()) {
                val value2 = map[mainWord]
                if (value2 != null) {
                    // 이전값과 머징.
                    val dupValue2 = duplicateCharList(value2)
                    finalValue = mergeSynonyms(dupValue2!!, finalValue)
                }
                //
                // 입력시 키워드는 공백제거.
                //
                map[mainWord] = finalValue
                // 공백이 포함되어 있다면, 제거한 단어도 함께 넣어준다.
                if (mainWord.hasWhitespaces()) {
                    map[CharVector(mainWord.toString(), ignoreCase).removeWhitespaces()] = finalValue
                }
            }
        }
    }

    // 중복제거한다. 중복이 발견되면 "" 로 치환한다.
    private fun dedupSynonym(list: Array<String>?) {
        if (list == null || list.size < 2) return
        for (i in list.indices) {
            for (j in i + 1 until list.size) {
                if (list[j].isNotEmpty() && list[i] == list[j]) {
                    list[j] = ""
                }
            }
        }
    }

    private fun mergeSynonyms(value2: Array<CharSequence>, value: Array<CharSequence>): Array<CharSequence> {
        var removedCount = 0
        val mutableValue2 = value2.toMutableList()
        for (i in value.indices) {
            for (j in i + 1 until mutableValue2.size) {
                if (mutableValue2[j] != null && value[i] == mutableValue2[j]) {
                    mutableValue2[j] = null as CharSequence
                    removedCount++
                }
            }
        }
        val newSize = mutableValue2.size + value.size - removedCount
        val list = arrayOfNulls<CharSequence>(newSize)
        var i = 0
        for (v in mutableValue2) {
            if (v != null) {
                list[i++] = v
            }
        }
        for (v in value) {
            if (v != null) {
                list[i++] = v
            }
        }
        @Suppress("UNCHECKED_CAST")
        return list as Array<CharSequence>
    }

    @Throws(IOException::class)
    override fun writeTo(out: OutputStream) {
        val bufferedOut = if (out is BufferedOutputStream) out else BufferedOutputStream(out)
        super.writeTo(bufferedOut)
        val output: DataOutput = OutputStreamDataOutput(bufferedOut)
        // write size of synonyms
        output.writeVInt(wordSet.size)
        // write synonyms
        val synonymIter = wordSet.iterator()
        while (synonymIter.hasNext()) {
            val value = CharVector.valueOf(synonymIter.next())!!
            output.writeUString(value.array(), value.offset(), value.length)
        }
        try { bufferedOut.flush() } catch (ignore: Exception) { }
    }

    @Throws(IOException::class)
    override fun readFrom(input: InputStream) {
        val bufferedIn = if (input is BufferedInputStream) input else BufferedInputStream(input)
        super.readFrom(bufferedIn)
        val dataInput: DataInput = InputStreamDataInput(bufferedIn)
        wordSet = HashSet()
        val size = dataInput.readVInt()
        for (entryInx in 0 until size) {
            wordSet.add(CharVector(dataInput.readUString(), ignoreCase))
        }
    }

    override fun reload(obj: Any?) {
        if (obj != null && obj is SynonymDictionary) {
            super.reload(obj)
            this.wordSet = obj.getWordSet()
        } else {
            throw IllegalArgumentException("Reload dictionary argument error. argument = $obj")
        }
    }
}

