        val valueString = values[0].toString()
        val nouns = valueString.split(",").toTypedArray()
        for (k in nouns.indices) {
            val noun = nouns[k].trim()
            if (noun.isNotEmpty()) {
                val word: CharSequence = CharVector(noun, ignoreCase)
                list.add(word)
                wordSet.add(word)
            }
        }

        val value = Array<CharSequence>(list.size) { j -> list[j] }
        if (value.isNotEmpty()) {
            map[mainWord] = value
        }
    }

    @Throws(IOException::class)
    override fun writeTo(out: OutputStream) {
        val bufferedOut = if (out is BufferedOutputStream) out else BufferedOutputStream(out)
        super.writeTo(bufferedOut)
        val output: DataOutput = OutputStreamDataOutput(bufferedOut)
        // write size of synonyms
        output.writeVInt(mainWordSet.size)
        // write synonyms
        val mainWordIter = mainWordSet.iterator()
        while (mainWordIter.hasNext()) {
            val value = CharVector.valueOf(mainWordIter.next())!!
            output.writeUString(value.array(), value.offset(), value.length)
        }
        // write size of synonyms
        output.writeVInt(wordSet.size)
        // write synonyms
        val wordIter = wordSet.iterator()
        while (wordIter.hasNext()) {
            val value = CharVector.valueOf(wordIter.next())!!
            output.writeUString(value.array(), value.offset(), value.length)
        }
        try { bufferedOut.flush() } catch (ignore: Exception) { }
    }

    @Throws(IOException::class)
    override fun readFrom(input: InputStream) {
        val bufferedIn = if (input is BufferedInputStream) input else BufferedInputStream(input)
        super.readFrom(bufferedIn)
        val dataInput: DataInput = InputStreamDataInput(bufferedIn)
        mainWordSet = HashSet()
        val mainWordSize = dataInput.readVInt()
        for (entryInx in 0 until mainWordSize) {
            mainWordSet.add(CharVector(dataInput.readUString(), ignoreCase))
        }
        wordSet = HashSet()
        val size = dataInput.readVInt()
        for (entryInx in 0 until size) {
            wordSet.add(CharVector(dataInput.readUString(), ignoreCase))
        }
    }

    override fun reload(obj: Any?) {
        if (obj != null && obj is CompoundDictionary) {
            super.reload(obj)
            this.mainWordSet = obj.getMainWordSet()
            this.wordSet = obj.getWordSet()
        } else {
            throw IllegalArgumentException("Reload dictionary argument error. argument = $obj")
        }
    }
}

