package com.danawa.search.analysis.dict

import org.apache.logging.log4j.Logger
import org.elasticsearch.common.logging.Loggers
import java.io.BufferedReader
import java.io.File
import java.io.FileInputStream
import java.io.FileNotFoundException
import java.io.InputStream
import java.io.InputStreamReader
import java.io.IOException

abstract class SourceDictionary<E>(
    @JvmField protected var ignoreCase: Boolean,
    @JvmField protected var label: String?,
    @JvmField protected var seq: Int,
    @JvmField protected var tokenType: String?,
    @JvmField protected var type: DictionaryType
) : ReloadableDictionary, WritableDictionary, ReadableDictionary {

    fun ignoreCase(): Boolean = ignoreCase
    fun label(): String? = label
    fun seq(): Int = seq
    fun tokenType(): String? = tokenType

    fun ignoreCase(ignoreCase: Boolean) {
        this.ignoreCase = ignoreCase
    }

    fun type(): DictionaryType = type

    fun loadSource(file: File) {
        var inputStream: InputStream? = null
        try {
            inputStream = FileInputStream(file)
            loadSource(inputStream)
        } catch (e: FileNotFoundException) {
            logger.error("사전소스파일을 찾을수 없습니다.", e)
        } finally {
            inputStream?.let {
                try {
                    it.close()
                } catch (ignore: IOException) { }
            }
        }
    }

    fun loadSource(inputStream: InputStream) {
        try {
            val br = BufferedReader(InputStreamReader(inputStream, "utf-8"))
            var line: String?
            while (br.readLine().also { line = it } != null) {
